package cl.antumapu.aulacontrol;

import android.Manifest;import android.app.*;import android.app.admin.DevicePolicyManager;import android.content.*;import android.content.pm.*;import android.graphics.*;import android.graphics.drawable.*;import android.media.projection.MediaProjectionManager;import android.net.Uri;import android.os.*;import android.provider.Settings;import android.text.InputType;import android.view.*;import android.widget.*;import java.net.*;import java.util.*;

public class MainActivity extends Activity{
 static final int CAP=42,USAGE=43,OVERLAY=44,ADMIN=45;static final int GREEN=Color.rgb(15,90,60),DARK=Color.rgb(8,56,38),ORANGE=Color.rgb(243,107,33),INK=Color.rgb(24,37,32),MUTED=Color.rgb(91,108,101),BG=Color.rgb(244,248,246);static final String LOGO="https://ia803101.us.archive.org/6/items/logos_20211117/color%20transparente.png";
 EditText user,course;String pendingUser="",pendingCourse="";long projectionRequestedAt;Handler ui=new Handler(Looper.getMainLooper());boolean maintenance=false;
 @Override public void onCreate(Bundle b){super.onCreate(b);if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{Manifest.permission.POST_NOTIFICATIONS},9);if(Core.ready(this)){agent();Managed.apply(this);route();}else firstUi();}
 @Override protected void onNewIntent(Intent i){super.onNewIntent(i);setIntent(i);route();}
 @Override protected void onResume(){super.onResume();if(Core.ready(this)&&!maintenance){Managed.apply(this);Managed.enter(this);if(!Core.user(this).isEmpty()&&!ScreenCaptureService.active)loginUi();}}
 @Override public void onUserInteraction(){super.onUserInteraction();if(!Core.user(this).isEmpty())Core.touch(this);}
 @Override public void onBackPressed(){if(maintenance){super.onBackPressed();return;}if(Core.ready(this)){route();return;}super.onBackPressed();}
 void route(){if(!Core.ready(this)){firstUi();return;}if(!Core.user(this).isEmpty()&&ScreenCaptureService.active&&ScreenCaptureService.lastFrameAt>0)launcherUi();else loginUi();}
 LinearLayout root(){LinearLayout r=new LinearLayout(this);r.setOrientation(LinearLayout.VERTICAL);r.setPadding(dp(22),dp(22),dp(22),dp(26));r.setBackgroundColor(BG);return r;}
 GradientDrawable bg(int c,float radius){GradientDrawable g=new GradientDrawable();g.setColor(c);g.setCornerRadius(dp((int)radius));return g;}
 TextView t(String s,int z,boolean bold){TextView v=new TextView(this);v.setText(s);v.setTextSize(z);v.setTextColor(INK);if(bold)v.setTypeface(null,1);return v;}
 TextView label(String s){TextView v=t(s,13,true);v.setTextColor(MUTED);v.setPadding(0,dp(8),0,dp(5));return v;}
 EditText in(String h,String v){EditText e=new EditText(this);e.setHint(h);e.setText(v);e.setTextSize(17);e.setTextColor(INK);e.setHintTextColor(Color.rgb(135,148,143));e.setSingleLine(true);e.setPadding(dp(16),dp(13),dp(16),dp(13));e.setBackground(bg(Color.WHITE,14));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,0,0,dp(10));e.setLayoutParams(p);return e;}
 EditText pw(String h){EditText e=in(h,"");e.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);return e;}
 Button btn(String s,int color){Button b=new Button(this);b.setText(s);b.setTextColor(Color.WHITE);b.setTextSize(15);b.setTypeface(null,1);b.setAllCaps(false);b.setBackground(bg(color,14));b.setPadding(dp(15),dp(12),dp(15),dp(12));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,dp(5),0,dp(5));b.setLayoutParams(p);return b;}
 TextView chip(String s,int c){TextView v=t(s,13,true);v.setTextColor(c);v.setBackground(bg(Color.WHITE,50));v.setPadding(dp(12),dp(7),dp(12),dp(7));return v;}
 int dp(int n){return(int)(n*getResources().getDisplayMetrics().density+.5f);}void toast(String s){Toast.makeText(this,s,Toast.LENGTH_SHORT).show();}
 View brand(){LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.HORIZONTAL);box.setGravity(Gravity.CENTER_VERTICAL);box.setPadding(dp(4),0,0,dp(14));ImageView im=new ImageView(this);im.setScaleType(ImageView.ScaleType.CENTER_INSIDE);im.setBackground(bg(Color.WHITE,16));box.addView(im,new LinearLayout.LayoutParams(dp(76),dp(76)));loadLogo(im);LinearLayout tx=new LinearLayout(this);tx.setOrientation(LinearLayout.VERTICAL);tx.setPadding(dp(14),0,0,0);TextView a=t("AulaControl",29,true);a.setTextColor(DARK);TextView b=t("Gestión y supervisión de aula",14,false);b.setTextColor(MUTED);tx.addView(a);tx.addView(b);box.addView(tx,new LinearLayout.LayoutParams(0,-2,1));return box;}
 void loadLogo(ImageView v){new Thread(()->{try{URLConnection c=new URL(LOGO).openConnection();c.setConnectTimeout(4500);c.setReadTimeout(4500);Bitmap bm=BitmapFactory.decodeStream(c.getInputStream());if(bm!=null)ui.post(()->v.setImageBitmap(bm));}catch(Exception ignored){ui.post(()->{TextView fallback=t("A",32,true);fallback.setTextColor(ORANGE);});}}).start();}
 LinearLayout card(){LinearLayout c=new LinearLayout(this);c.setOrientation(LinearLayout.VERTICAL);c.setPadding(dp(20),dp(18),dp(20),dp(18));c.setBackground(bg(Color.WHITE,20));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,dp(8),0,dp(10));c.setLayoutParams(p);return c;}
 void firstUi(){ScrollView sc=new ScrollView(this);LinearLayout r=root();sc.addView(r);r.addView(brand());LinearLayout hero=card();TextView h=t("Configura este dispositivo",25,true);h.setTextColor(DARK);hero.addView(h);TextView sub=t("Esta configuración se realiza una sola vez y queda protegida por contraseña administrativa.",14,false);sub.setTextColor(MUTED);sub.setPadding(0,dp(5),0,dp(12));hero.addView(sub);TextView id=chip("ID  ·  "+Core.id(this),GREEN);hero.addView(id);r.addView(hero);r.addView(label("Nombre del dispositivo"));EditText dn=in("Ej. Tablet 08","");r.addView(dn);r.addView(label("Clave técnica del establecimiento"));EditText key=in("Mínimo 10 caracteres","");r.addView(key);r.addView(label("Contraseña administrativa"));EditText p1=pw("Mínimo 6 caracteres");r.addView(p1);EditText p2=pw("Repite la contraseña");r.addView(p2);Button activate=btn("Activar AulaControl",GREEN);r.addView(activate);TextView foot=t("El modo administrado protege el launcher, las políticas y la desinstalación. Para protección completa, la tablet debe aprovisionarse como Device Owner.",12,false);foot.setTextColor(MUTED);foot.setPadding(dp(3),dp(8),dp(3),0);r.addView(foot);activate.setOnClickListener(v->{String a=dn.getText().toString().trim(),k=key.getText().toString().trim(),p=p1.getText().toString();if(a.length()<2){toast("Asigna un nombre al dispositivo");return;}if(k.length()<10){toast("La clave técnica debe tener al menos 10 caracteres");return;}if(p.length()<6){toast("La contraseña debe tener al menos 6 caracteres");return;}if(!p.equals(p2.getText().toString())){toast("Las contraseñas no coinciden");return;}Core.setup(this,a,k,p);activateAdmin();agent();Managed.apply(this);loginUi();new Handler(Looper.getMainLooper()).postDelayed(this::permissions,500);});setContentView(sc);}
 void loginUi(){Managed.enter(this);ScrollView sc=new ScrollView(this);LinearLayout r=root();sc.addView(r);r.addView(brand());LinearLayout top=card();LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.CENTER_VERTICAL);TextView dev=t(Core.dn(this),20,true);dev.setTextColor(DARK);row.addView(dev,new LinearLayout.LayoutParams(0,-2,1));row.addView(chip(Managed.owner(this)?"● Administrada":"● Modo básico",Managed.owner(this)?GREEN:ORANGE));top.addView(row);TextView ident=t("ID "+Core.id(this)+"  ·  "+Core.ip(),12,false);ident.setTextColor(MUTED);ident.setPadding(0,dp(6),0,0);top.addView(ident);r.addView(top);TextView hi=t("Inicia tu sesión",28,true);hi.setTextColor(DARK);r.addView(hi);TextView desc=t("Identifícate para habilitar este dispositivo institucional. Durante la sesión, el equipo funciona bajo supervisión docente.",14,false);desc.setTextColor(MUTED);desc.setPadding(0,dp(5),0,dp(12));r.addView(desc);r.addView(label("Nombre y apellido"));user=in("Escribe tu nombre","");r.addView(user);r.addView(label("Curso"));course=in("Ej. 8° Básico","");r.addView(course);Button login=btn("Iniciar sesión",GREEN);r.addView(login);TextView notice=t("Al iniciar sesión, Android solicitará la autorización necesaria para habilitar la supervisión. Si no se completa, el dispositivo permanecerá en esta pantalla.",12,false);notice.setTextColor(MUTED);notice.setPadding(dp(3),dp(9),dp(3),dp(10));r.addView(notice);Button admin=btn("Administración",DARK);admin.setAlpha(.92f);r.addView(admin);login.setOnClickListener(v->{pendingUser=user.getText().toString().trim();pendingCourse=course.getText().toString().trim();if(pendingUser.isEmpty()){toast("Ingresa tu nombre");return;}capture();});admin.setOnClickListener(v->askPw(this::adminPanel));setContentView(sc);}
 void capture(){MediaProjectionManager m=(MediaProjectionManager)getSystemService(MEDIA_PROJECTION_SERVICE);projectionRequestedAt=System.currentTimeMillis();startActivityForResult(m.createScreenCaptureIntent(),CAP);}
 @Override protected void onActivityResult(int rq,int rc,Intent data){super.onActivityResult(rq,rc,data);if(rq==CAP){if(rc==RESULT_OK&&data!=null){Intent i=new Intent(this,ScreenCaptureService.class);i.putExtra("rc",rc);i.putExtra("data",data);if(Build.VERSION.SDK_INT>=26)startForegroundService(i);else startService(i);waitProjection();}else{pendingUser="";pendingCourse="";new AlertDialog.Builder(this).setTitle("No fue posible iniciar la sesión").setMessage("Para utilizar este dispositivo debes completar el inicio de sesión.").setPositiveButton("Intentar nuevamente",null).show();}}else if(rq==USAGE||rq==OVERLAY)ui.postDelayed(this::permissions,250);else if(rq==ADMIN){Managed.apply(this);}}
 void waitProjection(){final long start=projectionRequestedAt;Toast.makeText(this,"Activando sesión…",Toast.LENGTH_SHORT).show();Runnable[] check=new Runnable[1];check[0]=()->{if(ScreenCaptureService.active&&ScreenCaptureService.lastFrameAt>=start){Core.login(this,pendingUser,pendingCourse);Core.touch(this);pendingUser="";pendingCourse="";agent();Managed.apply(this);launcherUi();return;}if(System.currentTimeMillis()-start>7000){stopService(new Intent(this,ScreenCaptureService.class));new AlertDialog.Builder(this).setTitle("Supervisión no disponible").setMessage("No se pudo confirmar la supervisión. Intenta iniciar sesión nuevamente.").setPositiveButton("Aceptar",(d,w)->loginUi()).show();return;}ui.postDelayed(check[0],250);};ui.post(check[0]);}
 void launcherUi(){if(Core.user(this).isEmpty()||!ScreenCaptureService.active){loginUi();return;}Managed.enter(this);ScrollView sc=new ScrollView(this);LinearLayout r=root();sc.addView(r);LinearLayout head=new LinearLayout(this);head.setGravity(Gravity.CENTER_VERTICAL);head.addView(brand(),new LinearLayout.LayoutParams(0,-2,1));TextView status=chip("● Supervisión activa",GREEN);head.addView(status);r.addView(head);LinearLayout welcome=card();TextView hello=t("Hola, "+Core.user(this),26,true);hello.setTextColor(DARK);welcome.addView(hello);TextView meta=t((Core.course(this).isEmpty()?"Sesión institucional":Core.course(this))+"  ·  "+Core.dn(this),14,false);meta.setTextColor(MUTED);meta.setPadding(0,dp(3),0,dp(9));welcome.addView(meta);LinearLayout chips=new LinearLayout(this);chips.setOrientation(LinearLayout.HORIZONTAL);chips.addView(chip("● En línea",GREEN));TextView c2=chip(Managed.owner(this)?"🔒 Modo administrado":"⚠ Protección parcial",Managed.owner(this)?GREEN:ORANGE);LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(-2,-2);cp.setMargins(dp(8),0,0,0);c2.setLayoutParams(cp);chips.addView(c2);welcome.addView(chips);r.addView(welcome);TextView appsTitle=t("Aplicaciones",20,true);appsTitle.setTextColor(DARK);appsTitle.setPadding(dp(2),dp(7),0,dp(8));r.addView(appsTitle);GridLayout grid=new GridLayout(this);grid.setColumnCount(getResources().getConfiguration().smallestScreenWidthDp>=600?4:3);grid.setUseDefaultMargins(false);List<ResolveInfo> apps=apps();for(ResolveInfo info:apps){LinearLayout app=new LinearLayout(this);app.setOrientation(LinearLayout.VERTICAL);app.setGravity(Gravity.CENTER);app.setPadding(dp(8),dp(14),dp(8),dp(12));app.setBackground(bg(Color.WHITE,18));GridLayout.LayoutParams gp=new GridLayout.LayoutParams();gp.width=0;gp.height=dp(118);gp.columnSpec=GridLayout.spec(GridLayout.UNDEFINED,1,1f);gp.setMargins(dp(5),dp(5),dp(5),dp(5));app.setLayoutParams(gp);ImageView icon=new ImageView(this);try{icon.setImageDrawable(info.loadIcon(getPackageManager()));}catch(Exception ignored){}app.addView(icon,new LinearLayout.LayoutParams(dp(48),dp(48)));TextView name=t(String.valueOf(info.loadLabel(getPackageManager())),13,true);name.setGravity(Gravity.CENTER);name.setMaxLines(2);name.setPadding(0,dp(7),0,0);app.addView(name);app.setOnClickListener(v->launch(info.activityInfo.packageName));grid.addView(app);}if(apps.isEmpty()){TextView none=t("No hay aplicaciones habilitadas para este perfil.",14,false);none.setTextColor(MUTED);grid.addView(none);}r.addView(grid);LinearLayout bottom=card();TextView live=t("Sesión supervisada",16,true);live.setTextColor(GREEN);bottom.addView(live);TextView detail=t("Último cuadro local: "+Math.max(0,System.currentTimeMillis()-ScreenCaptureService.lastFrameAt)+" ms  ·  IP "+Core.ip(),12,false);detail.setTextColor(MUTED);bottom.addView(detail);Button out=btn("Cerrar sesión",ORANGE);bottom.addView(out);TextView adm=t("Mantén pulsado aquí para administración",11,false);adm.setTextColor(MUTED);adm.setGravity(Gravity.CENTER);adm.setPadding(0,dp(8),0,0);adm.setOnLongClickListener(v->{askPw(this::adminPanel);return true;});bottom.addView(adm);r.addView(bottom);out.setOnClickListener(v->logout());setContentView(sc);}
 List<ResolveInfo> apps(){Intent q=new Intent(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_LAUNCHER);List<ResolveInfo> all=new ArrayList<>(getPackageManager().queryIntentActivities(q,PackageManager.MATCH_ALL));all.removeIf(x->{String p=x.activityInfo.packageName;return p.equals(getPackageName())||p.equals("com.android.settings")||p.equals("com.android.vending")||p.contains("packageinstaller")||p.contains("permissioncontroller");});all.sort((a,b)->String.valueOf(a.loadLabel(getPackageManager())).compareToIgnoreCase(String.valueOf(b.loadLabel(getPackageManager()))));return all;}
 void launch(String p){if(!ScreenCaptureService.active){loginUi();return;}try{Intent i=getPackageManager().getLaunchIntentForPackage(p);if(i!=null){i.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);startActivity(i);}}catch(Exception e){toast("No se pudo abrir la aplicación");}}
 void logout(){Core.logout(this);stopService(new Intent(this,ScreenCaptureService.class));loginUi();}
 void activateAdmin(){if(Managed.owner(this))return;DevicePolicyManager d=(DevicePolicyManager)getSystemService(DEVICE_POLICY_SERVICE);if(d.isAdminActive(Managed.admin(this)))return;Intent i=new Intent(DevicePolicyManager.ACTION_ADD_DEVICE_ADMIN);i.putExtra(DevicePolicyManager.EXTRA_DEVICE_ADMIN,Managed.admin(this));i.putExtra(DevicePolicyManager.EXTRA_ADD_EXPLANATION,"AulaControl utiliza la administración del dispositivo para proteger la configuración institucional.");startActivityForResult(i,ADMIN);}
 void adminPanel(){maintenance=true;Managed.exit(this);LinearLayout p=root();p.setPadding(dp(18),dp(8),dp(18),dp(8));TextView title=t("Administración",23,true);title.setTextColor(DARK);p.addView(title);p.addView(t(Core.dn(this)+"  ·  "+(Managed.owner(this)?"Device Owner activo":"Modo administrado pendiente"),13,false));Button edit=btn("Configuración de AulaControl",GREEN),perm=btn("Permisos de inactividad",DARK),settings=btn("Abrir ajustes Android",DARK),release=btn("Liberar dispositivo para mantenimiento",ORANGE),close=btn("Volver",GREEN);p.addView(edit);p.addView(perm);p.addView(settings);if(Managed.owner(this))p.addView(release);p.addView(close);Dialog d=new Dialog(this);d.setTitle("Administración");d.setContentView(p);Window w=d.getWindow();if(w!=null)w.setLayout(-1,-2);edit.setOnClickListener(v->{d.dismiss();config();});perm.setOnClickListener(v->{d.dismiss();permissions();});settings.setOnClickListener(v->{d.dismiss();try{startActivity(new Intent(Settings.ACTION_SETTINGS));}catch(Exception ignored){}});release.setOnClickListener(v->{new AlertDialog.Builder(this).setTitle("Liberar dispositivo").setMessage("Esto retirará la protección Device Owner y permitirá desinstalar AulaControl. Úsalo sólo para mantenimiento autorizado.").setNegativeButton("Cancelar",null).setPositiveButton("Liberar",(a,b)->{Managed.release(this);toast("Dispositivo liberado");d.dismiss();loginUi();}).show();});close.setOnClickListener(v->{d.dismiss();maintenance=false;Managed.enter(this);route();});d.setOnDismissListener(x->{if(maintenance){maintenance=false;Managed.enter(this);}});d.show();if(d.getWindow()!=null)d.getWindow().setLayout((int)(getResources().getDisplayMetrics().widthPixels*.9),-2);}
 void askPw(Runnable ok){EditText p=pw("Contraseña administrativa");new AlertDialog.Builder(this).setTitle("Acceso administrador").setMessage("Ingresa la contraseña para continuar.").setView(p).setNegativeButton("Cancelar",null).setPositiveButton("Desbloquear",(d,w)->{if(Core.checkPw(this,p.getText().toString()))ok.run();else toast("Contraseña incorrecta");}).show();}
 void config(){LinearLayout box=root();box.setPadding(dp(18),dp(6),dp(18),dp(6));EditText dn=in("Nombre del dispositivo",Core.dn(this));EditText k=in("Clave técnica",Core.key(this));EditText np=pw("Nueva contraseña (opcional)");EditText cp=pw("Repite nueva contraseña");box.addView(dn);box.addView(k);box.addView(np);box.addView(cp);new AlertDialog.Builder(this).setTitle("Configuración de AulaControl").setView(box).setNegativeButton("Cancelar",(d,w)->route()).setPositiveButton("Guardar",(d,w)->{String a=dn.getText().toString().trim(),x=k.getText().toString().trim(),p=np.getText().toString();if(a.length()<2||x.length()<10){toast("Revisa nombre y clave técnica");route();return;}if(!p.isEmpty()&&(p.length()<6||!p.equals(cp.getText().toString()))){toast("Revisa la nueva contraseña");route();return;}Core.config(this,a,x,p);stopService(new Intent(this,AgentService.class));agent();Managed.apply(this);route();}).show();}
 void permissions(){maintenance=true;Managed.exit(this);if(!Core.usage(this)){startActivityForResult(new Intent(Settings.ACTION_USAGE_ACCESS_SETTINGS),USAGE);return;}if(!Core.overlay(this)){startActivityForResult(new Intent(Settings.ACTION_MANAGE_OVERLAY_PERMISSION,Uri.parse("package:"+getPackageName())),OVERLAY);return;}maintenance=false;toast("Permisos de inactividad configurados");route();}
 void agent(){if(!Core.ready(this))return;Intent i=new Intent(this,AgentService.class);if(Build.VERSION.SDK_INT>=26)startForegroundService(i);else startService(i);}
}
